INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (20, 'Dua jalur jahitan tidak terbentuk dengan benar', 'Jahitan kiri dan kanan tidak rapi, tidak sejajar, atau hasil lockstitch tidak konsisten.', 'Ketegangan benang tidak seimbang, posisi jarum atau hook tidak tepat, atau pengaturan feed tidak sesuai.', 'Periksa threading kedua jalur benang, seimbangkan ketegangan benang, periksa posisi jarum dan hook, lalu lakukan uji jahit.', 'Matikan mesin sebelum melakukan pemeriksaan pada jarum, hook, atau mekanisme jahit.', 'Data spesifikasi JUKI LH-3578A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (20, 'Benang salah satu jarum sering putus', 'Salah satu benang jarum putus berulang saat mesin berjalan.', 'Jarum rusak atau tidak sesuai, jalur benang terlalu tegang, atau terdapat gesekan pada area jarum dan hook.', 'Ganti jarum yang sesuai, periksa jalur benang, kurangi ketegangan yang berlebihan, dan periksa area hook dari bagian yang kasar.', 'Matikan mesin sebelum mengganti jarum atau memeriksa jalur benang.', 'Data spesifikasi JUKI LH-3578A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (20, 'Benang bawah sering putus atau tidak stabil', 'Benang bobbin putus, tersangkut, atau ketegangan benang bawah tidak stabil.', 'Bobbin atau rumah bobbin tidak terpasang benar, ketegangan benang tidak sesuai, atau hook kotor.', 'Periksa pemasangan bobbin, bersihkan area hook, periksa ketegangan benang bawah, dan pastikan bobbin berputar dengan lancar.', 'Matikan mesin sebelum membersihkan area hook atau bobbin.', 'Data spesifikasi JUKI LH-3578A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (20, 'Salah satu jahitan loncat atau tidak terbentuk', 'Salah satu jalur jahitan mengalami skip stitch atau tidak membentuk ikatan benang dengan benar.', 'Jarum bengkok atau salah pemasangan, timing hook tidak tepat, atau kombinasi jarum dan benang tidak sesuai.', 'Ganti dan pasang jarum dengan benar, periksa hubungan jarum dengan hook, dan sesuaikan jenis jarum serta benang dengan material.', 'Matikan mesin sebelum memeriksa jarum dan mekanisme hook.', 'Data spesifikasi JUKI LH-3578A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (20, 'Jarak kedua jalur jahitan tidak sesuai needle gauge', 'Jarak antara dua jalur jahitan berbeda dari ukuran needle gauge yang digunakan.', 'Konfigurasi needle gauge tidak sesuai, posisi jarum tidak tepat, atau komponen needle bar mengalami perubahan posisi.', 'Periksa needle gauge, posisi kedua jarum, dan komponen needle bar. Sesuaikan kembali dengan konfigurasi mesin.', 'Matikan mesin sebelum melakukan penyetelan posisi jarum atau needle bar.', 'Data spesifikasi JUKI LH-3578A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (20, 'Panjang kedua jahitan tidak konsisten', 'Panjang stitch pada kedua jalur tidak seragam atau berubah selama proses menjahit.', 'Mekanisme drop feed tidak bergerak stabil, tekanan presser foot tidak sesuai, atau pengaturan panjang jahitan berubah.', 'Periksa mekanisme feed, tekanan presser foot, dan pengaturan panjang jahitan. Bersihkan area feed jika terdapat kotoran.', 'Matikan mesin sebelum membersihkan atau memeriksa mekanisme feed.', 'Data spesifikasi JUKI LH-3578A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (20, 'Jarum patah atau posisi kedua jarum tidak normal', 'Salah satu atau kedua jarum patah, bengkok, atau posisinya tidak sejajar.', 'Jarum tidak sesuai, pemasangan tidak benar, jarum menyentuh hook atau presser foot, atau terdapat kesalahan posisi mekanisme jarum.', 'Ganti jarum dengan tipe yang sesuai, pasang dan sejajarkan kedua jarum, lalu periksa clearance terhadap hook dan presser foot.', 'Matikan mesin dan pastikan pedal tidak aktif sebelum menangani jarum.', 'Data spesifikasi JUKI LH-3578A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (20, 'Pelumasan atau gerakan mesin tidak normal', 'Gerakan mesin terasa berat, suara tidak normal, atau bagian mekanisme bergerak kurang lancar.', 'Level pelumas tidak sesuai, saluran pelumasan terganggu, atau terdapat kotoran pada bagian mekanis.', 'Periksa sistem pelumasan otomatis, pastikan pelumas tersedia sesuai ketentuan mesin, bersihkan bagian yang kotor, dan periksa mekanisme yang bergerak.', 'Matikan mesin dan tunggu bagian yang bergerak berhenti sebelum melakukan pemeriksaan atau perawatan.', 'Data spesifikasi JUKI LH-3578A dan panduan pemeriksaan umum.');
